package org.slavicmyths.verify;
import java.util.*;import java.nio.file.*;import java.util.concurrent.*;
import net.minecraft.core.registries.*;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.presets.*;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import org.slavicmyths.chud.*;
/** Actual registered normal generator API equivalence on five seeds. No density or natural-start claim. */
@EventBusSubscriber(modid="slavicmyths") public final class Survey300 {
 static ServerLevel w;static long began;static int index;static final long[] SEEDS={30001,30002,8675309,2692026,-30005};static final int[][] CHUNKS={{0,0},{-1,0},{47,0},{1024,-1024}};static final List<Map<String,Object>> rows=new ArrayList<>();static final ExecutorService WORK=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"qa300-noise-equivalence");t.setDaemon(true);return t;});static Future<Map<String,Object>> pending;
 @SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent e){if(!"survey".equals(System.getProperty("slavicmyths.qa300")))return;w=e.getServer().overworld();began=System.nanoTime();}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(w==null)return;try{if(System.nanoTime()-began>180_000_000_000L)throw new IllegalStateException("survey bound");if(index==SEEDS.length*CHUNKS.length){finish(null);return;}if(pending==null){int n=index;var generator=(NoiseBasedChunkGenerator)w.registryAccess().registryOrThrow(Registries.WORLD_PRESET).getHolderOrThrow(WorldPresets.NORMAL).value().createWorldDimensions().overworld();long seed=SEEDS[n/CHUNKS.length];var state=RandomState.create(generator.generatorSettings().value(),w.registryAccess().lookupOrThrow(Registries.NOISE),seed);var xy=CHUNKS[n%CHUNKS.length];var at=new ChunkPos(xy[0],xy[1]);var c=new Structure.GenerationContext(w.registryAccess(),generator,generator.getBiomeSource(),state,w.getStructureManager(),seed,at,w,b->true);pending=WORK.submit(()->compare(c));return;}if(!pending.isDone())return;var row=pending.get();rows.add(row);System.out.println("QA300_NOISE "+row);pending=null;index++;}catch(Throwable x){finish(x);}}
 static Map<String,Object> compare(Structure.GenerationContext c){long t=System.nanoTime();var heights=ChudNoiseSurvey.heights(c,c.chunkPos());double batch=(System.nanoTime()-t)/1e6;t=System.nanoTime();var differences=new ArrayList<Map<String,Object>>();int count=0;for(int z=0;z<16;z++)for(int x=0;x<16;x++){int wx=c.chunkPos().getMinBlockX()+x,wz=c.chunkPos().getMinBlockZ()+z;int expected=c.chunkGenerator().getBaseHeight(wx,wz,Heightmap.Types.OCEAN_FLOOR_WG,c.heightAccessor(),c.randomState())-1;if(expected!=heights[(z<<4)|x]){count++;if(differences.size()<8)differences.add(Map.of("x",wx,"z",wz,"vanilla",expected,"batch",heights[(z<<4)|x]));}}return Map.of("seed",c.seed(),"chunk",List.of(c.chunkPos().x,c.chunkPos().z),"columns",256,"mismatches",count,"examples",differences,"batch_ms",batch,"vanilla_individual_ms",(System.nanoTime()-t)/1e6);}
 static void finish(Throwable error){var world=w;w=null;WORK.shutdownNow();try{var out=new LinkedHashMap<String,Object>();out.put("scope","RAW_NOISE_API_EQUIVALENCE_ONLY; no physical worldgen or gameplay claim");out.put("samples",rows);out.put("error",error==null?null:error.toString());out.put("status",error==null&&rows.size()==20&&rows.stream().allMatch(r->((Number)r.get("mismatches")).intValue()==0)?"PASS":"FAIL");out.put("elapsed_s",(System.nanoTime()-began)/1e9);Files.writeString(Path.of("survey300.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));if(error!=null)error.printStackTrace();}catch(Exception x){x.printStackTrace();}world.getServer().saveEverything(false,true,true);world.getServer().halt(false);}
}
